#include "analyzer/plugins/beattrackingrefiner.h"

#include <algorithm>
#include <cmath>

#include "track/beatfactory.h"

namespace mixxx {
namespace {

struct Onset {
    double position;
    double strength;
};

struct Hypothesis {
    double period = 0;
    double phase = 0;
    double score = 0;
    double precision = 0;
};

// Autonomously generated by an AI agent.
// Precision penalizes pulses without onsets; recall penalizes strong onsets
// left between pulses. Both are needed to distinguish half-time and 2:3 errors
// from a plausible slower pulse. Silence never contributes positive evidence.
// End of autonomously generated text.
Hypothesis evaluate(const std::vector<Onset>& peaks,
        double period,
        double phase,
        double tolerance) {
    const double start = peaks.front().position;
    const double end = peaks.back().position;
    const int first = static_cast<int>(std::ceil((start - phase) / period));
    const int last = static_cast<int>(std::floor((end - phase) / period));
    if (last - first < 15) {
        return {};
    }
    double matched = 0;
    double total = 0;
    int supported = 0;
    int previous = first - 1;
    for (const auto& peak : peaks) {
        total += peak.strength;
        const int index =
                static_cast<int>(std::round((peak.position - phase) / period));
        const double distance =
                std::abs(peak.position - phase - index * period);
        if (index >= first && index <= last && distance <= tolerance) {
            matched += peak.strength;
            if (index != previous) {
                ++supported;
                previous = index;
            }
        }
    }
    const double precision =
            static_cast<double>(supported) / (last - first + 1);
    const double recall = matched / total;
    return {period,
            phase,
            precision + recall > 0
                    ? 2 * precision * recall / (precision + recall)
                    : 0,
            precision};
}

Hypothesis bestPhase(
        const std::vector<Onset>& peaks, double period, double tolerance) {
    Hypothesis best;
    const size_t count = std::min(size_t(64), peaks.size());
    for (size_t i = 0; i < count; ++i) {
        const auto trial =
                evaluate(peaks, period, peaks[i].position, tolerance);
        if (trial.score > best.score) {
            best = trial;
        }
    }
    double adjustment = 0;
    double weight = 0;
    for (const auto& peak : peaks) {
        const double residual =
                std::remainder(peak.position - best.phase, period);
        if (std::abs(residual) <= tolerance) {
            adjustment += residual * peak.strength;
            weight += peak.strength;
        }
    }
    if (weight > 0) {
        best = evaluate(
                peaks, period, best.phase + adjustment / weight, tolerance);
    }
    return best;
}

} // namespace

QVector<audio::FramePos> refineBeatTrackingTempo(
        const QVector<audio::FramePos>& beats,
        const std::vector<double>& onsets,
        audio::SampleRate sampleRate,
        int stepSizeFrames) {
    if (beats.size() < 16 || onsets.size() < 3 || !sampleRate.isValid() ||
            stepSizeFrames <= 0) {
        return beats;
    }
    const auto grid =
            BeatFactory::makePreferredBeats(beats, {}, true, sampleRate);
    if (!grid) {
        return beats;
    }
    const auto bpm = grid->getBpmInRange(beats.front(), beats.back());
    if (!bpm.isValid()) {
        return beats;
    }
    const double period = 60. * sampleRate / bpm.value();
    const double tolerance = 1.5 * stepSizeFrames;
    const auto coherent = std::count_if(
            beats.begin(), beats.end(), [&](audio::FramePos beat) {
                return std::abs(std::remainder(
                               beat - grid->firstBeat(), period)) <= tolerance;
            });
    if (coherent < 0.8 * beats.size()) {
        return beats;
    }

    std::vector<Onset> peaks;
    double maximum = 0;
    for (size_t i = 1; i + 1 < onsets.size(); ++i) {
        if (std::isfinite(onsets[i]) && onsets[i] > onsets[i - 1] &&
                onsets[i] >= onsets[i + 1] && onsets[i] > 0) {
            peaks.push_back({(i + 0.5) * stepSizeFrames, onsets[i]});
            maximum = std::max(maximum, onsets[i]);
        }
    }
    if (peaks.size() < 16 || maximum <= 0) {
        return beats;
    }
    peaks.erase(std::remove_if(peaks.begin(),
                        peaks.end(),
                        [&](const Onset& onset) {
                            return onset.strength < 0.1 * maximum;
                        }),
            peaks.end());
    if (peaks.size() < 16) {
        return beats;
    }
    for (auto& peak : peaks) {
        peak.strength = std::sqrt(peak.strength / maximum);
    }

    const auto original = bestPhase(peaks, period, tolerance);
    auto best = original;
    double runnerUpScore = 0;
    for (const double multiplier : {0.5, 2. / 3., 1.5, 2.}) {
        const double candidateBpm = bpm.value() * multiplier;
        if (candidateBpm < 40 || candidateBpm > 240) {
            continue;
        }
        const auto candidate = bestPhase(peaks, period / multiplier, tolerance);
        if (candidate.precision < 0.8) {
            continue;
        }
        if (candidate.score > best.score) {
            runnerUpScore = best.score;
            best = candidate;
        } else {
            runnerUpScore = std::max(runnerUpScore, candidate.score);
        }
    }
    if (best.period == original.period || best.score < 0.85 ||
            best.score < original.score + 0.08 ||
            best.score < runnerUpScore + 0.04) {
        return beats;
    }

    QVector<audio::FramePos> result;
    const double first = best.phase +
            std::ceil((beats.front().value() - best.phase) / best.period) *
                    best.period;
    for (double position = first; position <= beats.back().value();
            position += best.period) {
        result.push_back(audio::FramePos(position));
    }
    return result;
}

} // namespace mixxx
